        if test $comparable_actual_version -lt $comparable_minimum_version ; then
          as_fn_error $? "gtest version is too old, at least version $GTEST_MINIMUM_VERSION is required" "$LINENO" 5
        fi
      fi
    fi
  fi


















  # Math library
  BASIC_JVM_LIBS="$LIBM"

  # Dynamic loading library
  if test "x$OPENJDK_TARGET_OS" = xlinux || test "x$OPENJDK_TARGET_OS" = xaix; then
    BASIC_JVM_LIBS="$BASIC_JVM_LIBS $LIBDL"
  fi

  # Threading library
  if test "x$OPENJDK_TARGET_OS" = xlinux || test "x$OPENJDK_TARGET_OS" = xaix; then
    BASIC_JVM_LIBS="$BASIC_JVM_LIBS $LIBPTHREAD"
  fi

  # librt - for timers (timer_* functions)
  if test "x$OPENJDK_TARGET_OS" = xlinux; then
    BASIC_JVM_LIBS="$BASIC_JVM_LIBS -lrt"
  fi

  # perfstat lib
  if test "x$OPENJDK_TARGET_OS" = xaix; then
    BASIC_JVM_LIBS="$BASIC_JVM_LIBS -lperfstat"
  fi

  if test "x$OPENJDK_TARGET_OS" = xwindows; then
    BASIC_JVM_LIBS="$BASIC_JVM_LIBS kernel32.lib user32.lib gdi32.lib winspool.lib \
        comdlg32.lib advapi32.lib shell32.lib ole32.lib oleaut32.lib powrprof.lib uuid.lib \
        ws2_32.lib winmm.lib version.lib psapi.lib"
  fi

  # Atomic library
  # 32-bit platforms needs fallback library for 8-byte atomic ops on Zero
  if   [[ " $JVM_VARIANTS " =~ " zero " ]]  ; then
    if test "x$OPENJDK_BUILD_OS" = xlinux &&
        test "x$OPENJDK_TARGET_CPU_BITS" = "x32"; then
      BASIC_JVM_LIBS_BUILD="$BASIC_JVM_LIBS_BUILD -latomic"
    fi
  fi


  # Atomic library
  # 32-bit platforms needs fallback library for 8-byte atomic ops on Zero
  if   [[ " $JVM_VARIANTS " =~ " zero " ]]  ; then
    if test "x$OPENJDK_TARGET_OS" = xlinux &&
        test "x$OPENJDK_TARGET_CPU_BITS" = "x32"; then
      BASIC_JVM_LIBS_TARGET="$BASIC_JVM_LIBS_TARGET -latomic"
    fi
  fi


  JVM_LIBS="$BASIC_JVM_LIBS $BASIC_JVM_LIBS_TARGET"
  OPENJDK_BUILD_JDKLIB_LIBS=""
  OPENJDK_BUILD_JVM_LIBS="$BASIC_JVM_LIBS $BASIC_JVM_LIBS_BUILD"






