        $AWK '{ for (i=1; i<=NF; i++) if (!match($i, /^-.*/)) printf("%s ", $i) }'`
    JVM_FEATURES_DISABLED=`$ECHO $user_jvm_feature_list | \
        $AWK '{ for (i=1; i<=NF; i++) if (match($i, /^-.*/)) printf("%s ", substr($i, 2))}'`

    # Verify that the user has provided only valid (or deprecated) features

  # grep filter function inspired by a comment to http://stackoverflow.com/a/1617326
  # Notice that the original variant fails on SLES 10 and 11
  # Some grep versions (at least bsd) behaves strangely on the base case with
  # no legal_values, so make it explicit.
  values_to_check=`$ECHO $JVM_FEATURES_ENABLED \
        $JVM_FEATURES_DISABLED | $TR ' ' '\n'`
  legal_values=`$ECHO $JVM_FEATURES_VALID $JVM_FEATURES_DEPRECATED | $TR ' ' '\n'`
  if test -z "$legal_values"; then
    invalid_features="$JVM_FEATURES_ENABLED \
        $JVM_FEATURES_DISABLED"
  else
    result=`$GREP -Fvx -- "$legal_values" <<< "$values_to_check" | $GREP -v '^$'`
    invalid_features=${result//$'\n'/ }
  fi

    if test "x$invalid_features" != x; then
      { printf "%s\n" "$as_me:${as_lineno-$LINENO}: Unknown JVM features specified: '$invalid_features'" >&5
printf "%s\n" "$as_me: Unknown JVM features specified: '$invalid_features'" >&6;}
      { printf "%s\n" "$as_me:${as_lineno-$LINENO}: The available JVM features are: '$JVM_FEATURES_VALID'" >&5
printf "%s\n" "$as_me: The available JVM features are: '$JVM_FEATURES_VALID'" >&6;}
      as_fn_error $? "Cannot continue" "$LINENO" 5
    fi

    # Check if the user has provided deprecated features

  # grep filter function inspired by a comment to http://stackoverflow.com/a/1617326
  # Notice that the original variant fails on SLES 10 and 11
  # Some grep versions (at least bsd) behaves strangely on the base case with
  # no legal_values, so make it explicit.
  values_to_check=`$ECHO $JVM_FEATURES_ENABLED \
        $JVM_FEATURES_DISABLED | $TR ' ' '\n'`
  illegal_values=`$ECHO $JVM_FEATURES_DEPRECATED | $TR ' ' '\n'`
  if test -z "$illegal_values"; then
    deprecated_features=""
  else
    result=`$GREP -Fx -- "$illegal_values" <<< "$values_to_check" | $GREP -v '^$'`
    deprecated_features=${result//$'\n'/ }
  fi

    if test "x$deprecated_features" != x; then
      { printf "%s\n" "$as_me:${as_lineno-$LINENO}: WARNING: Deprecated JVM features specified (will be ignored): '$deprecated_features'" >&5
